// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, type(uint256).max / 2);
        // the rightful owner is the deployer of c, i.e. this test contract
        address owner = address(this);
        vm.assume(c.smartfix_owner() == owner);
        vm.deal(address(c), amount);
        uint256 before = owner.balance;
        vm.prank(owner);
        c.sudicideAnyone();
        // rule: the caller (owner) receives the contract's entire balance
        assertTrue(owner.balance == before + amount && address(c).balance == 0);
    }
}
